"""Build docs/comparison_A_results.md and docs/hand_check_list.md from the output CSVs and the policy files (no hand-typed numbers)."""
import glob
import json
import sys
from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
from mgmt_tax.policy import load_policy  # noqa: E402

OUT = ROOT / "outputs" / "comparison_A"
N_YEARS = 15
d = pd.read_csv(OUT / "comparison_A_baseline.csv")
man = json.load(open(OUT / "manifest_baseline.json"))
rules = pd.read_csv(OUT / "rules_used_baseline.csv")
pol = load_policy(ROOT / "configs" / "policy_be_2026_supplied.yaml", ROOT / "configs" / "assumptions.yaml", ROOT / "configs" / "proposals.yaml")
PROFITS = sorted(d.profit_level.unique())
k = lambda x: f"{x / 1000:,.0f}k"  # noqa: E731
pct = lambda x: f"{100 * x:.1f}%"  # noqa: E731
eur = lambda x: f"{x:,.0f}"  # noqa: E731


def md(df: pd.DataFrame) -> str:
    head = "| " + " | ".join(df.columns) + " |\n|" + "|".join("---" for _ in df.columns) + "|\n"
    return head + "\n".join("| " + " | ".join(str(v) for v in r) + " |" for r in df.itertuples(index=False)) + "\n"


def sel(df, hh="single", co="mature"):
    return df[(df.household == hh) & (df.cohort == co)]


L = []
L.append("# Comparison A: employee vs sole trader vs one-person BV, current law (WP2 first part)\n")
L.append(f"> **{man['banner']}**\n>\n> **Nothing below is a statement about real Belgian policy effects.** Every result depends on the rules in `configs/policy_be_2026_supplied.yaml`, "
         f"which were supplied by the project owner and have **not** been confirmed against primary sources. Of the {man['n_rules_used']} rules these results use, status counts are "
         f"`{man['rule_status_counts']}`; none is `checked`. The values to confirm by hand are in [`hand_check_list.md`](hand_check_list.md). "
         f"No P1/P2/P3 proposal is modelled here (comparison B).\n")
L.append("Generated by `scripts/make_report_a.py` from `outputs/comparison_A/` "
         f"(code commit `{man['git_commit']}`, seed {man['seed']}, {man['n_rep']} paired replicates, ledger residual max {man['max_ledger_residual']:.1e}). Re-run `scripts/run_comparison_a.py` then this script to reproduce.\n")

L.append("## 1. What is compared\n")
L.append("- **Same economic activity.** *Profit level* = expected annual revenue billed to the client (for the employee: total employer cost). All arrangements face the same revenue path each year "
         "(paired shocks: replicate-mean exactly 1; employee gets the wage residual, business forms also the business shock), the same household and the same starting wealth. Horizon 2026-2040 (15 years), constant 2026 euros, **no indexation of thresholds**.\n"
         "- **Household** = household spending need (placeholder: 24,000 first adult, +12,000 partner, +6,000 per child), minus an employed partner's fixed net income (placeholder 30,000). Under the supplied rules taxation is individual, so household type changes the owner's outcome **only through this liquidity constraint**; family tax rules (child allowances, marital quotient) were not supplied and are not modelled.\n"
         "- **Cohort**: *mature* = the company is already in its fifth taxable period in 2026 (the EUR 51,000 pay condition applies from year 1); *new* = founded 2026 (periods 1-4 exempt from the pay condition under my reading of the supplied wording).\n"
         "- **BV strategies** (19): pay rule (`thr` = pay EUR 51,000 or all profit if lower, keeps the 20% rate; `min` = smallest pay that finances the household need, i.e. the 'minimum salary' strategy; `shell` = all profit paid out) x what happens to post-tax profit (annual dividend; retained in the free reserve; allocated to the liquidation reserve) x exit route "
         "(VVPRbis 18% dividend, ordinary 30% liquidation, liquidation reserve paid out on liquidation (10% total), liquidation-reserve dividend after the 3-year lock (18.82%)), with interim lumps after 3 or 5 years. `BV_BEST` is the strategy with the highest mean terminal wealth in the cell (anti-abuse variants excluded).\n"
         "- **Metric** = terminal wealth in 2040 after liquidating the company and paying every tax (private wealth + company, same spending in all arrangements), paired against the sole trader / employee in the same replicate. "
         "Positive = better than the comparator. Real return on retained funds = **0%** in the baseline (so the timing of extraction has no value by construction; see sensitivities).\n")

L.append("## 2. Headline: the BV advantage by profit level (single owner, mature company)\n")
s = sel(d)
rows = []
for p in PROFITS:
    b = s[(s.arrangement == "BV_BEST") & (s.profit_level == p)].iloc[0]
    e = s[(s.arrangement == "EMPLOYEE") & (s.profit_level == p)].iloc[0]
    rows.append({"revenue/yr": eur(p), "best BV strategy": b.best_strategy.replace("BV:", ""), "BV vs sole trader, EUR/yr": eur(b.adv_vs_sole_wealth_mean / N_YEARS),
                 "% of revenue": pct(b.adv_vs_sole_pct_of_revenue), "p10 / p90 (EUR, 15 yrs)": f"{eur(b.adv_vs_sole_wealth_p10)} / {eur(b.adv_vs_sole_wealth_p90)}",
                 "BV vs employee, EUR/yr": eur(b.adv_vs_emp_wealth_mean / N_YEARS), "% of revenue ": pct(b.adv_vs_emp_pct_of_revenue),
                 "sole trader vs employee, EUR/yr": eur(-e.adv_vs_sole_wealth_mean / N_YEARS)})
L.append(md(pd.DataFrame(rows)))
L.append("Reading: at EUR 100,000 of revenue the best one-person-BV strategy leaves the owner about "
         f"{eur(s[(s.arrangement == 'BV_BEST') & (s.profit_level == 100000)].adv_vs_sole_wealth_mean.iloc[0] / N_YEARS)} a year better off than a sole trader. "
         "At EUR 40,000 the BV loses (fixed costs of EUR 4,000 + 409 a year). The advantage is not an estimate of what real owners get: it is what the supplied rules give a tax-minimising owner with perfect foresight of the rules.\n")

L.append("## 3. By strategy and exit route (advantage over the sole trader, EUR per year, single owner, mature company)\n")
sub = s[s.arrangement.str.startswith("BV:")]
tab = sub.pivot_table(index="arrangement", columns="profit_level", values="adv_vs_sole_wealth_mean") / N_YEARS
order = ["shell_full_pay"] + [f"{t}_{x}" for t in ("thr", "min") for x in ("dist_ord", "dist_vvpr", "ret_vvpr_end", "ret_vvpr_k3", "ret_vvpr_k5", "ret_ord_liq", "lr_liq", "lr_div_k5", "lr_liq_antiabuse")]
tab = tab.reindex([f"BV:{o}" for o in order])
tab.index = [i.replace("BV:", "") for i in tab.index]
tab.columns = [k(c) for c in tab.columns]
tab = tab.round(0).astype(int).map(lambda x: f"{x:,}")
tab.insert(0, "strategy", tab.index)
L.append(md(tab.reset_index(drop=True)))
L.append("Key to names: `thr`/`min` pay rule; `dist_ord`/`dist_vvpr` dividend every year at 30% / 18%; `ret_vvpr_*` retain and take a VVPRbis dividend at the end / after 3 / after 5 years; `ret_ord_liq` retain and liquidate at 30%; "
         "`lr_liq` liquidation reserve then liquidation (10% in total); `lr_div_k5` liquidation reserve with a dividend after 5 years of the vintages past the lock (18.82% on those); `*_antiabuse` the liquidation payout is taxed as an ordinary dividend (30%, rate not supplied).\n\n"
         "**Findings that follow mechanically from the supplied rules**\n\n"
         "1. With a 0% return, *retaining then paying a VVPRbis dividend after 3, 5 or 15 years gives exactly the same result as paying the 18% dividend every year* (`ret_vvpr_*` = `dist_vvpr`): the tax advantage comes from the **rate gap** between the 18% (or 10%) exit and the 45-50% marginal personal tax plus contributions on pay, not from deferral. Deferral only matters through returns on retained funds (section 6).\n"
         "2. Without the reduced VVPRbis rate (`dist_ord` / `ret_ord_liq`, 30%) the advantage over the sole trader is roughly halved at EUR 100,000 revenue; it stays positive.\n"
         "3. The liquidation-reserve-then-liquidation route (10% in total) is the cheapest exit at every profit level. If the 2026 anti-abuse rule applies (owner becomes director of a similar company within 3 years - plausible for a consultant who continues working), the route loses most of its value (rate on the payout assumed 30%, **not supplied**).\n"
         "4. The 'minimum salary' strategy (`min`) beats paying EUR 51,000 up to about EUR 130,000 of revenue even though it forfeits the 20% rate; above that the reduced rate on the first EUR 100,000 of profit is worth more (best strategy switches to `thr`).\n")

L.append("## 4. Where the advantage comes from (EUR 100,000 revenue, 15-year totals, single owner, mature company)\n")
cols = ["tax_pit", "tax_ssc_employee", "tax_ssc_employer", "tax_ssc_self", "tax_corp_tax", "tax_company_contribution", "tax_lr_levy", "tax_dividend_wht", "tax_liquidation_tax"]
s100 = s[s.profit_level == 100000].set_index("arrangement")
sel_arr = ["EMPLOYEE", "SOLE_TRADER", "BV:thr_dist_ord", "BV:thr_dist_vvpr", "BV:min_dist_vvpr", "BV:min_lr_liq", "BV_BEST"]
dec = s100.loc[sel_arr, cols + ["total_tax_and_contrib_mean", "ssc_mean", "tax_excl_ssc_mean", "pension_base_per_year_mean", "owner_pay_per_year_mean", "wealth_end_mean"]].round(0)
dec.columns = [c.replace("tax_", "") for c in dec.columns]
dec = dec.map(lambda x: f"{x:,.0f}")
dec.insert(0, "arrangement", dec.index)
L.append(md(dec.reset_index(drop=True)))
b100 = s100.loc["BV_BEST"]
L.append(f"Against the sole trader the best BV saves {eur(b100.tax_saved_vs_sole_total)} in total tax and contributions, of which **{eur(b100.ssc_saved_vs_sole)} is lower social contributions** (director pay is smaller than profit) and "
         f"{eur(b100.tax_saved_vs_sole_excl_ssc)} is lower taxes proper. Against the employee it saves {eur(b100.tax_saved_vs_emp_total)}, of which **{eur(b100.ssc_saved_vs_emp)} is social contributions** and only "
         f"{eur(b100.tax_saved_vs_emp_excl_ssc)} taxes proper. **The lower contributions buy lower pension-relevant income** (column `pension_base_per_year_mean`: employee {eur(s100.loc['EMPLOYEE', 'pension_base_per_year_mean'])}, sole trader {eur(s100.loc['SOLE_TRADER', 'pension_base_per_year_mean'])}, "
         f"best BV {eur(b100.pension_base_per_year_mean)} a year), so part of the 'advantage' is a lower pension entitlement, not a free gain. No euro value is put on pensions here (no verified pension rule). "
         "Note also that the employee comparator is handicapped by the open inputs set to zero (professional-expense lump sum, work bonus, employer reductions); see section 6.\n")

L.append("## 5. Household type and company age (BV_BEST advantage over the sole trader, % of revenue)\n")
b = d[d.arrangement == "BV_BEST"]
t = b[b.profit_level.isin([60000, 100000, 200000])].pivot_table(index=["household", "cohort"], columns="profit_level", values="adv_vs_sole_pct_of_revenue")
t = t.map(pct).reset_index()
t.columns = ["household", "cohort"] + [k(c) for c in t.columns[2:]]
L.append(md(t))
L.append("A household that needs more income from the owner (one earner, children) has to take more pay, which reduces the room for low-taxed retention; a second earner raises the advantage. "
         "A new company gains a little from the four exempt periods. **Because the supplied rules tax individuals separately, these differences are purely liquidity effects** - the family-tax rules that matter in reality are open inputs.\n")

L.append("## 6. Sensitivity to open inputs and interpretations (BV vs sole trader, EUR over 15 years, EUR 100,000 revenue, single, mature)\n")
rows = []
labels = {"baseline": "baseline", "return_2pct": "real return on retained funds 2%", "return_3pct": "real return 3%", "lr_dividend_total_18pct": "liquidation-reserve dividend total = 18% (owner's figure) instead of 18.82%",
          "lock_plus_one_year": "lock counted one more calendar year", "no_exempt_first_periods": "no exemption in first 4 periods (affects new cohort only)",
          "se_14pct_above_ceiling": "self-employed contribution 14.16% above 2nd ceiling (default: none)", "employee_deduction_3000": "HYPOTHETICAL fixed EUR 3,000 deduction for the employee (not a rule)",
          "no_pay_covers_profit_rule": "pay condition always EUR 51,000, no 'covers profit' clause (bites only below about EUR 55,000 revenue)", "anti_abuse_rate_0": "anti-abuse rule without effect (rate 0)"}
for f in sorted(glob.glob(str(OUT / "comparison_A_*.csv"))):
    x = pd.read_csv(f)
    lab = x.scenario.iloc[0]
    if lab not in labels:
        continue
    r = sel(x)
    r = r[r.profit_level == 100000].set_index("arrangement")
    rows.append({"case": labels[lab], "BV_BEST": eur(r.loc["BV_BEST", "adv_vs_sole_wealth_mean"]), "min_lr_liq": eur(r.loc["BV:min_lr_liq", "adv_vs_sole_wealth_mean"]),
                 "min_lr_div_k5": eur(r.loc["BV:min_lr_div_k5", "adv_vs_sole_wealth_mean"]), "thr_dist_vvpr": eur(r.loc["BV:thr_dist_vvpr", "adv_vs_sole_wealth_mean"]),
                 "thr_ret_vvpr_end": eur(r.loc["BV:thr_ret_vvpr_end", "adv_vs_sole_wealth_mean"]), "min_lr_liq anti-abuse": eur(r.loc["BV:min_lr_liq_antiabuse", "adv_vs_sole_wealth_mean"]),
                 "employee vs sole": eur(r.loc["EMPLOYEE", "adv_vs_sole_wealth_mean"])})
# new-cohort rows for the case that only affects new companies
for lab, name in (("baseline", "baseline, NEW company (periods 1-4 exempt from the pay condition)"), ("no_exempt_first_periods", "NEW company, no exemption in first 4 periods")):
    x = pd.read_csv(OUT / f"comparison_A_{lab}.csv")
    r = sel(x, co="new")
    r = r[r.profit_level == 100000].set_index("arrangement")
    rows.append({"case": name, "BV_BEST": eur(r.loc["BV_BEST", "adv_vs_sole_wealth_mean"]), "min_lr_liq": eur(r.loc["BV:min_lr_liq", "adv_vs_sole_wealth_mean"]),
                 "min_lr_div_k5": eur(r.loc["BV:min_lr_div_k5", "adv_vs_sole_wealth_mean"]), "thr_dist_vvpr": eur(r.loc["BV:thr_dist_vvpr", "adv_vs_sole_wealth_mean"]),
                 "thr_ret_vvpr_end": eur(r.loc["BV:thr_ret_vvpr_end", "adv_vs_sole_wealth_mean"]), "min_lr_liq anti-abuse": eur(r.loc["BV:min_lr_liq_antiabuse", "adv_vs_sole_wealth_mean"]),
                 "employee vs sole": eur(r.loc["EMPLOYEE", "adv_vs_sole_wealth_mean"])})
df6 = pd.DataFrame(rows)
df6["_o"] = [0 if c == "baseline" else 1 for c in df6.case]
L.append(md(df6.sort_values("_o", kind="stable").drop(columns="_o")))
L.append("Cases change one input at a time and are not alternative laws. Same replicates in every case.\n")

L.append("## 7. What this does and does not show\n")
_s = sel(d)
_b = {p: _s[(_s.arrangement == "BV_BEST") & (_s.profit_level == p)].iloc[0] for p in (100000, 250000)}
_ssc_share = _b[100000].ssc_saved_vs_sole / _b[100000].tax_saved_vs_sole_total
L.append(f"- It shows the **size and structure** of the BV advantage that the *supplied* rules imply, by profit level, strategy and exit route. For a single owner it is {eur(_b[100000].adv_vs_sole_wealth_mean / N_YEARS)} a year at EUR 100,000 of revenue ({pct(_b[100000].adv_vs_sole_pct_of_revenue)}) rising to {eur(_b[250000].adv_vs_sole_wealth_mean / N_YEARS)} at EUR 250,000 ({pct(_b[250000].adv_vs_sole_pct_of_revenue)}) against a sole trader. At EUR 100,000, {pct(_ssc_share)} of the total tax-and-contribution saving is lower social contributions (section 4); the rest comes from the gap between the 10-18% exit rates and the 45-50% marginal rate on pay.\n"
         "- It does **not** show how many owners behave this way, nor that real owners attain these results (perfect foresight, perfect timing, VVPRbis eligibility assumed, no pension saving for the comparators, no third-pillar saving or individual pension commitment, no indexation).\n"
         "- **Not modelled, all of which could change the level:** the possible dividend-vs-paid-up-capital condition on the reduced rate (the engine refuses to run if it is switched on); VVPRbis eligibility conditions and any waiting period; benefits in kind (20% rule); tax-advantaged private pension saving for sole traders and employees; family tax rules; municipal differences; social-fund fees; VAT; losses carried forward.\n"
         "- Employee comparator: professional-expense lump sums, work bonus and employer reductions were not supplied and are set to zero, which **understates** the employee's net income and therefore **overstates** the BV's edge over the employee.\n"
         "- The headline numbers should be re-run after the values in `hand_check_list.md` are confirmed.\n")
(ROOT / "docs" / "comparison_A_results.md").write_text("\n".join(L), encoding="utf-8")

# ------------------------------------------------------------------ hand check list
H = ["# Values to confirm by hand (generated from the policy files)\n",
     "Generated by `scripts/make_report_a.py`. Every rule below has `hand_check: true` in `configs/*.yaml`: it is supplied (not independently confirmed), my interpretation of ambiguous wording, an open input with a default, or an assumption that matters. "
     "`used` = the comparison-A runs actually depended on it.\n",
     "| rule id | value used | status | used | what to check / source |", "|---|---|---|---|---|"]
used = set(rules.rule_id)
for rid, r in pol.rules.items():
    if r.hand_check:
        H.append(f"| `{rid}` | {str(r.value)[:70]} | **{r.status}** | {'yes' if rid in used else 'no'} | {r.source}{(' - ' + r.note) if r.note else ''} |")
H.append("\n## Not modelled but possibly material (check whether they apply)\n")
H.append("1. A possible dividend-vs-paid-up-capital condition on the 20% rate (rule `corp.dividend_capital_condition`; the engine raises if enabled).\n"
         "2. VVPRbis: eligibility conditions and any waiting period (the model lets an eligible owner pay it every year; `asm.vvprbis_eligible`).\n"
         "3. Employee: professional-expense lump sum, work bonus, employer reductions.\n"
         "4. Family tax rules (child allowances, marital quotient) and the tax on private returns (movable-income rate), irrelevant only at 0% return.\n"
         "5. Treatment of self-employed contributions above the second ceiling, social-fund fees, whether the base is net of the contribution (`se.base_net_of_contribution`).\n"
         "6. Consequence of the anti-abuse rule for a liquidation-reserve payout (the model uses 30% on the payout).\n")
(ROOT / "docs" / "hand_check_list.md").write_text("\n".join(H), encoding="utf-8")
print("report written")
